questions.tests:
def flaky(fail_times, error=None):
    state = {"calls": 0}
    def fn():
        state["calls"] += 1
        if state["calls"] <= fail_times:
            raise (error or TransientError("throttled"))
        return "ok"
    return fn, state

def test_success_first_try():
    fn, state = flaky(0)
    assert call_with_retry(fn, sleep=lambda d: None) == "ok" and state["calls"] == 1
def test_success_after_two_failures():
    fn, state = flaky(2)
    assert call_with_retry(fn, tries=3, sleep=lambda d: None) == "ok" and state["calls"] == 3
def test_delays_double():
    delays = []
    fn, _ = flaky(2)
    call_with_retry(fn, tries=3, base_delay=0.5, sleep=delays.append)
    assert delays == [0.5, 1.0]
def test_reraises_after_last_try():
    fn, state = flaky(10)
    try:
        call_with_retry(fn, tries=3, sleep=lambda d: None)
    except TransientError:
        assert state["calls"] == 3
        return
    assert False, "should re-raise TransientError"
def test_no_sleep_after_last_try():
    delays = []
    fn, _ = flaky(10)
    try:
        call_with_retry(fn, tries=3, base_delay=1, sleep=delays.append)
    except TransientError:
        pass
    assert len(delays) == 2
def test_other_errors_not_retried():
    fn, state = flaky(1, error=ValueError("bad request"))
    try:
        call_with_retry(fn, tries=3, sleep=lambda d: None)
    except ValueError:
        assert state["calls"] == 1
        return
    assert False, "a ValueError must propagate at once"
def test_tries_below_one():
    try:
        call_with_retry(lambda: "ok", tries=0)
    except ValueError:
        return
    assert False, "tries=0 must raise ValueError"

questions.model:
import time

class TransientError(Exception):
    pass

def call_with_retry(fn, tries=3, base_delay=0.5, sleep=time.sleep):
    if tries < 1:
        raise ValueError("tries must be >= 1")
    for attempt in range(1, tries + 1):
        try:
            return fn()
        except TransientError:
            if attempt == tries:
                raise
            sleep(base_delay * 2 ** (attempt - 1))

explanation.fr:
```python
class TransientError(Exception): ...

def call_with_retry(fn, *, tries=3, base_delay=0.5, sleep=time.sleep):
    if tries < 1:
        raise ValueError("tries must be >= 1")
    for attempt in range(1, tries + 1):
        try:
            return fn()
        except TransientError:
            if attempt == tries:
                raise
            sleep(base_delay * 2 ** (attempt - 1) * (1 + random.random() * 0.1))
```

Cinq points à dire à voix haute :

1. On ne réessaie que les erreurs **transitoires** (limitation de débit, délai, 503).
2. L'attente double, avec un peu de hasard (*jitter*).
3. `sleep` est injecté : le test tourne en 0 seconde.
4. On ne réessaie une écriture que si elle est **idempotente**.
5. Le dernier échec remonte, et le mode de secours écrit la raison.

explanation.en:
```python
class TransientError(Exception): ...

def call_with_retry(fn, *, tries=3, base_delay=0.5, sleep=time.sleep):
    if tries < 1:
        raise ValueError("tries must be >= 1")
    for attempt in range(1, tries + 1):
        try:
            return fn()
        except TransientError:
            if attempt == tries:
                raise
            sleep(base_delay * 2 ** (attempt - 1) * (1 + random.random() * 0.1))
```

Five points to say out loud:

1. Retry only **transient** errors (throttling, timeouts, 503).
2. The wait doubles, with a little randomness (*jitter*).
3. `sleep` is injected: the test runs in 0 seconds.
4. Retry a write only if it is **idempotent**.
5. The last failure propagates, and the fallback logs the reason.
